const normalizeName = (value) => String(value || "").toLowerCase().replaceAll("ё", "е").replace(/[«»"“”„]/g, "").replace(/\s+/g, " ").trim();

const mergeCategory = (baseCategory, sourceGroups) => {
  if (!sourceGroups?.length) return baseCategory;
  const baseItems = baseCategory.groups.flatMap((group) => group.items);
  const baseByName = new Map(baseItems.map((item) => [normalizeName(item.name), item]));
  const consumedIds = new Set();
  const mergedGroups = sourceGroups.map((group) => ({
    ...group,
    items: group.items.map((sourceItem) => {
      const existing = baseByName.get(normalizeName(sourceItem.name));
      if (!existing) return sourceItem;
      consumedIds.add(existing.id);
      return { ...existing, name: sourceItem.name, unit: sourceItem.unit, mount: sourceItem.mount, dismount: sourceItem.dismount ?? existing.dismount ?? 0 };
    }),
  }));
  const sourceNames = new Set(sourceGroups.flatMap((group) => group.items.map((item) => normalizeName(item.name))));
  const leftovers = baseItems.filter((item) => !consumedIds.has(item.id) && !sourceNames.has(normalizeName(item.name)));
  if (leftovers.length) mergedGroups.push({ id: `${baseCategory.id}_legacy_extra`, name: "Другие работы", items: leftovers });
  return { ...baseCategory, groups: mergedGroups };
};

export const CALC_CATEGORIES = BASE_CALC_CATEGORIES.map((category) => mergeCategory(category, SOURCE_ADDITIONS[category.id]));

